<script setup lang="ts">import {onMounted,ref} from 'vue';import {ElMessage} from 'element-plus';import {fetchPrivateQuestions,publishPrivateQuestion,type PrivateQuestion} from '../../api/teacher/privateQuestions';const rows=ref<PrivateQuestion[]>([]);const loading=ref(false);async function load(){loading.value=true;try{rows.value=await fetchPrivateQuestions()}finally{loading.value=false}}async function publish(id:number){try{await publishPrivateQuestion(id);ElMessage.success('已发布到绑定班级，不进入全局题库。');await load()}catch(e:any){ElMessage.error(e.message||'发布失败')}}onMounted(load)</script>
<template><main class="workspace-page"><header class="workspace-header"><div><h1>我的班级题库</h1><p>应用层隔离：仅本人及绑定任课班级学生可见；数据库所有者和备份管理员理论上仍可访问存储数据。</p></div><el-button type="primary">新建私有题</el-button></header><el-alert title="上传前先选择本人 ACTIVE 任课范围；后端会再次校验，Excel 中不能填写任课关系 ID。图片为可选项。" type="info" :closable="false"/><el-table v-loading="loading" :data="rows"><el-table-column prop="className" label="班级"/><el-table-column prop="subjectName" label="学科"/><el-table-column prop="questionType" label="题型"/><el-table-column prop="stem" label="题干" show-overflow-tooltip/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='DRAFT'" type="primary" plain @click="publish(row.id)">发布到班级</el-button></template></el-table-column></el-table></main></template>
